"""Ground heightmap of a world generated by generate.py: PNG render, chunk-border seams, model comparison.

    python3 tools/worldcheck/heightmap.py run/t1 --png run/t1-relief.png
    python3 tools/worldcheck/heightmap.py run/t1 --expected run/t1-expected.bin
    python3 tools/worldcheck/heightmap.py run/t1 --compare run/t1b

Ground = min(OCEAN_FLOOR, MOTION_BLOCKING_NO_LEAVES) of the saved chunk heightmaps: the highest solid
block without water and (mostly) without tree canopies; tree trunks remain. Water = columns where the
water surface is above the ground.

--expected reads surface heights exported by the terrain preview for the same square:
    ./gradlew terrainPreview --args="--seed SEED --center CX CZ --size N --scale 1 --heights FILE"
with CX, CZ, N printed by this script (from worldcheck.json). The expected top block of a column is
ceil(height) - 1; caves, cave entrances, trees and other features make the real ground differ locally.
"""
import argparse
import json
import math
import os
import struct
import sys
import zlib

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from anvil import read_chunk  # noqa: E402

SEA = 63


def decode_heightmap(longs, min_y, height):
    bits = math.ceil(math.log2(height + 1))
    per_long, mask, out = 64 // bits, (1 << bits) - 1, []
    for value in longs:
        value &= 0xFFFFFFFFFFFFFFFF
        for _ in range(per_long):
            if len(out) < 256:
                out.append((value & mask) + min_y - 1)
            value >>= bits
    return out


class Ground:
    def __init__(self, path):
        with open(os.path.join(path, "worldcheck.json")) as f:
            self.meta = json.load(f)
        r = self.meta["radius"]
        self.lo_x, self.lo_z, self.hi_x, self.hi_z = self.meta.get("chunk_range", [-r, -r, r - 1, r - 1])
        self.x0, self.z0 = self.lo_x * 16, self.lo_z * 16
        self.w = (self.hi_x - self.lo_x + 1) * 16
        self.h = (self.hi_z - self.lo_z + 1) * 16
        self.ground = [[0] * self.w for _ in range(self.h)]
        self.water = [[False] * self.w for _ in range(self.h)]
        region = os.path.join(path, "region")
        for cx in range(self.lo_x, self.hi_x + 1):
            for cz in range(self.lo_z, self.hi_z + 1):
                nbt = read_chunk(region, cx, cz)
                if nbt is None or nbt.get("Status") != "minecraft:full":
                    raise SystemExit("chunk %d,%d of %s is missing or not fully generated" % (cx, cz, path))
                min_y = nbt["yPos"] * 16
                height = 768 if min_y == -256 else 384
                maps = nbt["Heightmaps"]
                floor = decode_heightmap(maps["OCEAN_FLOOR"], min_y, height)
                no_leaves = decode_heightmap(maps["MOTION_BLOCKING_NO_LEAVES"], min_y, height)
                for i in range(256):
                    x = (cx - self.lo_x) * 16 + (i & 15)
                    z = (cz - self.lo_z) * 16 + (i >> 4)
                    self.ground[z][x] = min(floor[i], no_leaves[i])
                    self.water[z][x] = no_leaves[i] > floor[i] and no_leaves[i] <= SEA + 1
        probe = self.meta.get("probe_column")
        if probe:
            px, pz = probe[0] - self.x0, probe[1] - self.z0
            if 0 <= px < self.w and 0 <= pz < self.h:
                # The setblock probe column holds glass up to the build limit; copy a neighbour.
                self.ground[pz][px] = self.ground[pz][px + 1] if px + 1 < self.w else self.ground[pz][px - 1]


def seams(g):
    inside = [0.0, 0, 0]
    border = [0.0, 0, 0]
    for z in range(g.h):
        row = g.ground[z]
        for x in range(g.w - 1):
            d = abs(row[x + 1] - row[x])
            bucket = border if (g.x0 + x) % 16 == 15 else inside
            bucket[0] += d
            bucket[1] += 1
            bucket[2] = max(bucket[2], d)
    for z in range(g.h - 1):
        for x in range(g.w):
            d = abs(g.ground[z + 1][x] - g.ground[z][x])
            bucket = border if (g.z0 + z) % 16 == 15 else inside
            bucket[0] += d
            bucket[1] += 1
            bucket[2] = max(bucket[2], d)
    print("neighbour height steps: inside chunks mean %.3f max %d (%d pairs); across chunk borders mean %.3f max %d (%d pairs)"
          % (inside[0] / inside[1], inside[2], inside[1], border[0] / border[1], border[2], border[1]))


def compare_expected(g, path):
    n = g.w
    with open(path, "rb") as f:
        data = f.read()
    if len(data) != n * n * 4:
        raise SystemExit("%s holds %d values, expected %d (size %d)" % (path, len(data) // 4, n * n, n))
    values = struct.unpack("<%df" % (n * n), data)
    hist = {}
    exact = within3 = total = 0
    worst = []
    for z in range(g.h):
        for x in range(g.w):
            expected = math.ceil(values[z * n + x]) - 1
            d = g.ground[z][x] - expected
            total += 1
            exact += abs(d) <= 1
            within3 += abs(d) <= 3
            key = max(-20, min(20, d))
            hist[key] = hist.get(key, 0) + 1
    print("ground vs terrain model (top block = ceil(surface) - 1): |diff| <= 1 in %.2f%%, <= 3 in %.2f%% of %d columns"
          % (100.0 * exact / total, 100.0 * within3 / total, total))
    print("difference histogram (ground - expected, clamped to +-20):",
          ", ".join("%d: %d" % (k, hist[k]) for k in sorted(hist)))


def compare_worlds(a, b):
    same = total = worst = 0
    for z in range(a.h):
        for x in range(a.w):
            total += 1
            d = abs(a.ground[z][x] - b.ground[z][x])
            same += d == 0
            worst = max(worst, d)
    print("ground identical in %.3f%% of columns, max difference %d" % (100.0 * same / total, worst))


def color(v, water):
    if water or v < SEA - 1:
        d = min(1.0, max(0.0, (SEA - v) / 70.0))
        return (int(70 - 55 * d), int(130 - 95 * d), int(190 - 90 * d))
    stops = [(63, 196, 190, 140), (66, 104, 156, 82), (90, 88, 140, 66), (120, 132, 156, 84), (160, 160, 146, 98),
             (210, 140, 116, 90), (270, 128, 120, 116), (330, 200, 200, 204), (420, 250, 250, 255)]
    for i in range(len(stops) - 1):
        if v < stops[i + 1][0]:
            a, b = stops[i], stops[i + 1]
            t = max(0.0, (v - a[0]) / (b[0] - a[0]))
            return tuple(int(a[k] + t * (b[k] - a[k])) for k in (1, 2, 3))
    return (250, 250, 255)


def write_png(g, path):
    lx, ly, lz = -0.5, 0.6, -0.62
    ll = math.sqrt(lx * lx + ly * ly + lz * lz)
    rows = []
    for z in range(g.h):
        row = bytearray([0])
        for x in range(g.w):
            v = g.ground[z][x]
            dx = (g.ground[z][min(g.w - 1, x + 1)] - g.ground[z][max(0, x - 1)]) / 2.0
            dz = (g.ground[min(g.h - 1, z + 1)][x] - g.ground[max(0, z - 1)][x]) / 2.0
            if g.water[z][x]:
                dx = dz = 0.0
            shade = (-dx * lx + ly - dz * lz) / ll / math.sqrt(dx * dx + 1 + dz * dz)
            s = 0.35 + 0.75 * max(0.0, shade)
            row.extend(min(255, int(c * s)) for c in color(v, g.water[z][x]))
        rows.append(bytes(row))
    raw = zlib.compress(b"".join(rows), 6)

    def chunk(kind, data):
        return struct.pack(">I", len(data)) + kind + data + struct.pack(">I", zlib.crc32(kind + data) & 0xFFFFFFFF)

    with open(path, "wb") as f:
        f.write(b"\x89PNG\r\n\x1a\n")
        f.write(chunk(b"IHDR", struct.pack(">IIBBBBB", g.w, g.h, 8, 2, 0, 0, 0)))
        f.write(chunk(b"IDAT", raw))
        f.write(chunk(b"IEND", b""))


def main():
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("world")
    p.add_argument("--png", help="write a hillshaded relief map (1 pixel per block, north up)")
    p.add_argument("--expected", help="surface heights exported by the terrain preview for the same square")
    p.add_argument("--compare", help="a second world of the same square: share of identical ground heights")
    args = p.parse_args()

    g = Ground(args.world)
    values = [v for row in g.ground for v in row]
    land = [v for row, wrow in zip(g.ground, g.water) for v, w in zip(row, wrow) if not w]
    print("== %s: %d x %d blocks from x %d z %d (terrain preview: --center %d %d --size %d)"
          % (args.world, g.w, g.h, g.x0, g.z0, g.x0 + g.w // 2, g.z0 + g.h // 2, g.w))
    print("ground: min %d, max %d, mean %.1f; water columns %.1f%%"
          % (min(values), max(values), sum(values) / len(values), 100.0 * (len(values) - len(land)) / len(values)))
    seams(g)
    if args.expected:
        compare_expected(g, args.expected)
    if args.compare:
        compare_worlds(g, Ground(args.compare))
    if args.png:
        write_png(g, args.png)
        print("wrote", args.png)


if __name__ == "__main__":
    main()
